function maximumProduct(nums, k) {
  const MOD = 1e9 + 7;
  const heap = [...nums].sort((a, b) => a - b);
  const n = heap.length;

  for (let step = 0; step < k; step++) {
    heap[0]++;
    let i = 0;
    while (true) {
      const left = 2 * i + 1;
      const right = 2 * i + 2;
      let smallest = i;
      if (left < n && heap[left] < heap[smallest]) {
        smallest = left;
      }
      if (right < n && heap[right] < heap[smallest]) {
        smallest = right;
      }
      if (smallest === i) {
        break;
      }
      [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
      i = smallest;
    }
  }

  let product = 1;
  for (const value of heap) {
    product = (product * value) % MOD;
  }
  return product;
}

