function maximumProduct(nums, k) {
  // Try every way to share out at most k increments and keep the exact (BigInt) maximum.
  const values = nums.slice();
  let best = -1n;
  const spread = (index, remaining) => {
    if (index === values.length) {
      let total = 1n;
      for (const v of values) total *= BigInt(v);
      if (total > best) best = total;
      return;
    }
    const base = values[index];
    for (let add = 0; add <= remaining; add++) {
      values[index] = base + add;
      spread(index + 1, remaining - add);
    }
    values[index] = base;
  };
  spread(0, k);
  return Number(best % 1000000007n);
}

