function generate(rand, size) {
  if (size === 'large') {
    const mode = Math.floor(rand() * 3);
    const top = mode === 0 ? 1000000 : mode === 1 ? 100 : 5;
    const nums = Array.from({ length: 2000 }, () => Math.floor(rand() * (top + 1)));
    return [nums, 100000 - Math.floor(rand() * 1000)];
  }
  const n = 1 + Math.floor(rand() * 5);
  const nums = Array.from({ length: n }, () => {
    const r = rand();
    if (r < 0.1) return 1000000 - Math.floor(rand() * 3);
    return Math.floor(rand() * 7);
  });
  return [nums, 1 + Math.floor(rand() * 8)];
}
